"use client";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { Download, Printer } from "lucide-react";

const MOCK_PRESCRIPTION = {
  id: 1,
  date: "2024-06-01T10:00:00Z",
  doctor: {
    name: "Dr. Mehta",
    specialization: "Cardiologist",
    avatar: "https://randomuser.me/api/portraits/men/32.jpg",
  },
  patient: {
    name: "Sujit Kumar",
    age: 32,
    gender: "Male",
  },
  medicines: [
    { name: "Amlodipine", dosage: "5mg", frequency: "Once daily", duration: "30 days", instructions: "After breakfast" },
    { name: "Atorvastatin", dosage: "10mg", frequency: "Once daily", duration: "30 days", instructions: "At bedtime" },
  ],
  notes: "Monitor blood pressure daily. Return for follow-up in 1 month.",
  status: "Active",
};

function formatDate(dt) {
  const d = new Date(dt);
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
}

export default function PrescriptionPage() {
  const prescription = MOCK_PRESCRIPTION;

  if (!prescription) {
    return (
      <div className="flex flex-col items-center justify-center py-16">
        <span className="text-6xl mb-4">💊</span>
        <div className="text-gray-500 text-lg">No prescription found.</div>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto py-8 px-2 w-full">
      <Card className="rounded-xl shadow p-6">
        <CardHeader className="flex flex-row items-center gap-4 p-0 pb-4 border-b border-gray-100">
          <Avatar className="w-12 h-12">
            <AvatarImage src={prescription.doctor.avatar} alt={prescription.doctor.name} />
            <AvatarFallback>{prescription.doctor.name.charAt(0)}</AvatarFallback>
          </Avatar>
          <div className="flex-1">
            <CardTitle className="text-lg font-semibold text-gray-800 mb-1">{prescription.doctor.name}</CardTitle>
            <div className="text-blue-600 text-sm font-medium">{prescription.doctor.specialization}</div>
          </div>
          <Badge color="green">{prescription.status}</Badge>
        </CardHeader>
        <CardContent className="flex flex-col gap-4 p-0 pt-4">
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-8 text-sm text-gray-600">
            <div><span className="font-medium">Patient:</span> {prescription.patient.name}</div>
            <div><span className="font-medium">Age:</span> {prescription.patient.age}</div>
            <div><span className="font-medium">Gender:</span> {prescription.patient.gender}</div>
            <div><span className="font-medium">Date:</span> {formatDate(prescription.date)}</div>
          </div>
          <div className="mt-2">
            <div className="font-semibold text-gray-800 mb-2">Medicines</div>
            <div className="overflow-x-auto">
              <table className="min-w-full text-sm border rounded-lg">
                <thead>
                  <tr className="bg-gray-50 text-gray-600">
                    <th className="py-2 px-3 text-left">Name</th>
                    <th className="py-2 px-3 text-left">Dosage</th>
                    <th className="py-2 px-3 text-left">Frequency</th>
                    <th className="py-2 px-3 text-left">Duration</th>
                    <th className="py-2 px-3 text-left">Instructions</th>
                  </tr>
                </thead>
                <tbody>
                  {prescription.medicines.map((med, idx) => (
                    <tr key={idx} className="border-b last:border-b-0">
                      <td className="py-2 px-3 font-medium text-gray-800">{med.name}</td>
                      <td className="py-2 px-3">{med.dosage}</td>
                      <td className="py-2 px-3">{med.frequency}</td>
                      <td className="py-2 px-3">{med.duration}</td>
                      <td className="py-2 px-3">{med.instructions}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
          <div className="mt-4">
            <div className="font-semibold text-gray-800 mb-1">Doctor's Notes</div>
            <div className="text-gray-700 text-sm">{prescription.notes}</div>
          </div>
          <div className="flex gap-3 mt-6">
            <Button variant="outline" className="flex items-center gap-2"><Download size={16} />Download PDF</Button>
            <Button variant="outline" className="flex items-center gap-2"><Printer size={16} />Print</Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
} 